UPDATE wms_ware_sku
   SET stock_locked = stock_locked + #{count}
 WHERE id = #{id}
   AND stock - stock_locked >= #{count}

UPDATE wms_ware_sku
   SET stock_locked = stock_locked - #{count}
 WHERE id = #{id}
   AND stock_locked >= #{count}

UPDATE wms_ware_sku
   SET stock_locked = stock_locked - #{count}
 WHERE sku_id = #{skuId}
   AND stock_locked >= #{count}
 ORDER BY id
 LIMIT 1

UPDATE wms_ware_sku
   SET stock_locked = stock_locked - #{count}
 WHERE sku_id = #{skuId}
   AND ware_id = #{wareId}
   AND stock_locked >= #{count}

UPDATE wms_ware_sku
   SET stock = stock - #{count},
       stock_locked = stock_locked - #{count}
 WHERE sku_id = #{skuId}
   AND stock_locked >= #{count}
   AND stock >= #{count}
 ORDER BY id
 LIMIT 1

UPDATE wms_ware_sku
   SET stock = stock - #{count},
       stock_locked = stock_locked - #{count}
 WHERE sku_id = #{skuId}
   AND ware_id = #{wareId}
   AND stock_locked >= #{count}
   AND stock >= #{count}

UPDATE wms_ware_sku
   SET stock = stock + #{count}
 WHERE id = #{id}
